+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrity = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
+        validateIntegrity(integrity);
+        if (INTEGRITY_REPAIR.equals(integrity) && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String configuredFileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
+        if (hasConfiguredRuleViolationFileNameStrategy && properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot configure %s when a rule violation file name strategy was supplied to the constructor",
+                    FILE_NAMES_PROPERTY_NAME));
+        }
+        ruleViolationFileNameStrategy = hasConfiguredRuleViolationFileNameStrategy
+                ? configuredRuleViolationFileNameStrategy
+                : createRuleViolationFileNameStrategy(configuredFileNames);
+        randomFileNames = !hasConfiguredRuleViolationFileNameStrategy && FILE_NAMES_RANDOM.equals(configuredFileNames);
