+        String configuredPath = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        Path configuredFolderPath = Paths.get(configuredPath).toAbsolutePath().normalize();
+        if (!Files.isDirectory(configuredFolderPath)) {
+            if (Files.exists(configuredFolderPath) || INTEGRITY_FAIL.equals(integrity) || !storeCreationAllowed) {
+                throwCannotCreateStore(configuredFolderPath);
+            }
+            try {
+                Files.createDirectories(configuredFolderPath);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        try {
+            storeFolderPath = configuredFolderPath.toRealPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        storeFolder = storeFolderPath.toFile();
+        storedRulesPath = storeFolderPath.resolve(STORED_RULES_FILE_NAME);
+        String storeKey = storedRulesPath.toString();
+        Object storeLock = STORE_LOCKS_BY_PATH.computeIfAbsent(storeKey, ignored -> new Object());
+        synchronized (storeLock) {
+            ensureStoredRulesFile();
+            storedRules = getOrCreateStoredRules(storedRulesPath);
+            storedRules.reload();
+            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesPath);
+            if (!INTEGRITY_IGNORE.equals(integrity)) {
+                IntegrityState state = inspectIntegrity();
+                if (INTEGRITY_FAIL.equals(integrity) && state.hasProblems()) {
