+    private void validateIntegrity(String value) {
+        if (!INTEGRITY_REPAIR.equals(value) && !INTEGRITY_FAIL.equals(value) && !INTEGRITY_IGNORE.equals(value)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid value for %s: '%s' (accepted values are repair, fail and ignore)",
+                    INTEGRITY_PROPERTY_NAME, value));
+        }
+    }
+
+    private RuleViolationFileNameStrategy createRuleViolationFileNameStrategy(String value) {
+        if (FILE_NAMES_RANDOM.equals(value)) {
+            return new RandomRuleViolationFileNameStrategy();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(value)) {
+            return new DescriptionRuleViolationFileNameStrategy();
+        }
+        try {
+            Class<?> strategyClass = Class.forName(value);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            if (!Modifier.isPublic(constructor.getModifiers())) {
+                throw new IllegalArgumentException("does not have a public no-argument constructor");
+            }
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s='%s'; expected 'random', 'description' or a fully-qualified strategy class with a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, value), e);
+        }
+    }
+
+    private void throwCannotCreateStore(Path folder) {
