+
+    private void ensureStoredRulesFile() {
+        boolean exists = Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(storedRulesPath);
+        if (!exists) {
+            if (!storeCreationAllowed || INTEGRITY_FAIL.equals(integrity)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+            try {
+                Files.createFile(storedRulesPath);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+        if (!Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)
+                || !storeFolderPath.equals(storedRulesPath.getParent())) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The violation store index must be a regular file directly in %s: %s",
+                    storeFolderPath, storedRulesPath));
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(Path file) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(file.toString(), ignored -> new FileSyncedProperties(file));
+        } catch (RuntimeException e) {
+            throw e;
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeLock()) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storeLock()) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (INTEGRITY_REPAIR.equals(integrity) && violations.isEmpty()) {
+                if (existingFileName == null) {
+                    return;
+                }
+                removeStoredRule(description, existingFileName);
+                return;
+            }
+
+            String fileName = existingFileName == null ? createFileNameForSave(description) : existingFileName;
+            Path target = validateWritableFileName(fileName);
