+
+    private String createFileNameForSave(String description) {
+        String fileName = createFileName(description);
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name strategy returned no name for rule '%s'", description));
+        }
+        return fileName;
+    }
+
+    private String createFileNameForIntegrity(String description) {
+        String fileName = createFileName(description);
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Rule violation file name strategy returned no name for rule '%s'", description));
+        }
+        return fileName;
+    }
+
+    private String createFileName(String description) {
+        try {
+            return ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw e;
+        }
+    }
+
+    private Path validateWritableFileName(String fileName) {
+        try {
+            Path path = resolvePathFollowingLinks(fileName);
+            if (!storeFolderPath.equals(path.getParent())) {
+                throw unsafeFileName(fileName);
+            }
+            if (path.equals(storedRulesPath) || sameFileIfPossible(path, storedRulesPath)) {
+                throw unsafeFileName(fileName);
+            }
+            return path;
+        } catch (InvalidPathException | IOException e) {
+            throw new StoreUpdateFailedException(String.format("Cannot safely store violations in file '%s'", fileName));
+        }
+    }
+
+    private StoreUpdateFailedException unsafeFileName(String fileName) {
+        return new StoreUpdateFailedException(String.format(
+                "Cannot safely store violations in file '%s': it must lead to a file directly in the store folder and must not lead to %s",
+                fileName, STORED_RULES_FILE_NAME));
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private void removeStoredRule(String description, String fileName) {
+        IntegrityState state = inspectIntegrity();
+        Entry entry = state.entriesByDescription.get(description);
+        if (entry != null && !state.sharedEntries.contains(entry)) {
+            deleteRuleFile(fileName);
+        }
+        storedRules.remove(description);
+    }
+
+    private void deleteRuleFile(String fileName) {
+        try {
+            Path namedPath = storeFolderPath.resolve(fileName);
+            if (namedPath.equals(storedRulesPath) || sameFileIfPossible(namedPath, storedRulesPath)) {
+                throw new IOException("The index cannot be deleted");
+            }
+            if (Files.isSymbolicLink(namedPath)) {
+                Path target = resolvePathFollowingLinks(fileName);
+                if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+                    Files.delete(target);
+                }
+                Files.deleteIfExists(namedPath);
+            } else {
+                Files.deleteIfExists(resolvePathFollowingLinks(fileName));
+            }
+        } catch (InvalidPathException | IOException e) {
+            throw new StoreUpdateFailedException(String.format("Cannot delete stored rule file '%s'", fileName), e);
+        }
+    }
+
+    private void deleteIfPossible(Path path) {
+        try {
+            if (!path.equals(storedRulesPath) && !sameFileIfPossible(path, storedRulesPath)) {
+                Files.deleteIfExists(path);
+            }
+        } catch (IOException ignored) {
+            // The original update failure is the useful one to report.
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeLock()) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (ONLY_LINE_BREAKS_PATTERN.matcher(violationsText).matches()) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(storeFolderPath.resolve(fileName).toFile()), UTF_8));
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreReadException(e);
+        }
+    }
