+        Set<Entry> sharedEntries = findSharedEntries(entries);
+        Set<Entry> brokenEntries = new HashSet<>();
+        Set<Entry> resolvedEntries = new HashSet<>();
+        for (Entry entry : entries) {
+            FileResolution resolution = resolveEntry(entry.fileName);
+            entry.resolution = resolution;
+            if (!resolution.validRuleFile) {
+                brokenEntries.add(entry);
+            } else if (isOnlyLineBreaks(readStoreFile(entry.fileName))) {
+                resolvedEntries.add(entry);
+            }
+        }
