+        Map<String, Integer> derivedNameCounts = new HashMap<>();
+        for (String name : derivedNames.values()) {
+            derivedNameCounts.put(name, derivedNameCounts.containsKey(name) ? derivedNameCounts.get(name) + 1 : 1);
+        }
+        Set<Entry> misplacedEntries = new HashSet<>();
+        Set<Entry> collidingEntries = new HashSet<>();
+        Set<Entry> occupiedEntries = new HashSet<>();
