+            String derivedName = derivedNames.get(entry);
+            boolean misplaced = !entry.fileName.equals(derivedName);
+            if (misplaced) {
+                misplacedEntries.add(entry);
+                if (!isDirectDestination(derivedName) || destinationExists(derivedName)
+                        || recordedByAnotherEntry(entries, entry, derivedName)) {
+                    occupiedEntries.add(entry);
+                }
+            }
+            if (derivedNameCounts.get(derivedName) > 1) {
+                collidingEntries.add(entry);
+            }
+        }
