+        List<Path> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityState(entries, entriesByDescription, derivedNames, brokenEntries, resolvedEntries,
+                sharedEntries, misplacedEntries, collidingEntries, occupiedEntries, unownedFiles);
+    }
+
+    private Set<Entry> findSharedEntries(List<Entry> entries) {
+        Set<Entry> result = new HashSet<>();
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (first.fileName.equals(second.fileName) || sameFileIfPossible(first.fileName, second.fileName)) {
+                    result.add(first);
+                    result.add(second);
+                }
+            }
+        }
+        return result;
+    }
+
+    private boolean sameFileIfPossible(String firstFileName, String secondFileName) {
+        try {
+            return sameFileIfPossible(storeFolderPath.resolve(firstFileName), storeFolderPath.resolve(secondFileName));
+        } catch (InvalidPathException e) {
+            return false;
+        }
+    }
+
+    private boolean sameFileIfPossible(Path first, Path second) {
+        try {
+            return Files.exists(first) && Files.exists(second) && Files.isSameFile(first, second);
+        } catch (IOException | SecurityException e) {
+            return false;
+        }
+    }
+
+    private FileResolution resolveEntry(String fileName) {
+        try {
+            Path resolved = resolvePathFollowingLinks(fileName);
+            boolean valid = storeFolderPath.equals(resolved.getParent())
+                    && !resolved.equals(storedRulesPath)
+                    && Files.isRegularFile(resolved);
+            return new FileResolution(valid, resolved);
+        } catch (InvalidPathException | IOException e) {
+            return new FileResolution(false, null);
+        }
+    }
+
+    private boolean isOnlyLineBreaks(String contents) {
+        return ONLY_LINE_BREAKS_PATTERN.matcher(contents).matches();
+    }
+
+    private boolean isDirectDestination(String fileName) {
+        try {
+            return storeFolderPath.equals(resolvePathFollowingLinks(fileName).getParent())
+                    && !resolvePathFollowingLinks(fileName).equals(storedRulesPath);
+        } catch (InvalidPathException | IOException e) {
+            return false;
+        }
+    }
+
+    private boolean destinationExists(String fileName) {
+        try {
+            Path path = storeFolderPath.resolve(fileName);
+            return Files.exists(path, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(path);
+        } catch (InvalidPathException e) {
+            return false;
+        }
+    }
+
+    private boolean recordedByAnotherEntry(List<Entry> entries, Entry current, String name) {
+        for (Entry entry : entries) {
+            if (entry != current && entry.fileName.equals(name)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private List<Path> findUnownedFiles(List<Entry> entries) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
+            for (Path file : files) {
+                if (file.equals(storedRulesPath) || !isRegularFileDirectlyInStoreFolder(file)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (sameFileIfPossible(file, storeFolderPath.resolve(entry.fileName))) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private boolean isRegularFileDirectlyInStoreFolder(Path file) {
+        try {
+            Path resolved = file.toRealPath();
+            return storeFolderPath.equals(resolved.getParent()) && Files.isRegularFile(resolved);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void repair(IntegrityState state) {
+        boolean changed = false;
+        for (Entry entry : state.entries) {
+            if (state.sharedEntries.contains(entry)) {
+                continue;
+            }
+            if (state.brokenEntries.contains(entry)) {
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (state.resolvedEntries.contains(entry)) {
+                deleteRuleFile(entry.fileName);
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (state.misplacedEntries.contains(entry)
+                    && !state.collidingEntries.contains(entry)
+                    && !state.occupiedEntries.contains(entry)) {
+                moveToDerivedName(entry, state.derivedNames.get(entry));
+                storedRules.put(entry.description, state.derivedNames.get(entry));
+                changed = true;
+            }
+        }
+        // FileSyncedProperties writes each change immediately only through these methods. A repair with no changed
+        // entry therefore never touches the index; the flag documents that this is intentional and protects future
+        // refactorings from adding an unconditional sync.
+        if (changed) {
