+        }
+    }
+
+    private void moveToDerivedName(Entry entry, String derivedName) {
+        try {
+            Path source = storeFolderPath.resolve(entry.fileName);
+            Path target = resolvePathFollowingLinks(derivedName);
+            if (Files.isSymbolicLink(source)) {
+                Path sourceTarget = resolvePathFollowingLinks(entry.fileName);
+                Files.move(sourceTarget, target);
+                Files.deleteIfExists(source);
+            } else {
+                Files.move(resolvePathFollowingLinks(entry.fileName), target);
+            }
+        } catch (InvalidPathException | IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not move misplaced violation file for rule '%s' to '%s'", entry.description, derivedName), e);
+        }
+    }
+
+    private String reportEntry(Entry entry) {
+        return "  '" + entry.description + "' -> '" + entry.fileName + "'";
+    }
+
+    private String reportEntries(String title, Set<Entry> entries) {
+        if (entries.isEmpty()) {
+            return "";
+        }
+        List<Entry> sorted = new ArrayList<>(entries);
+        sorted.sort(ENTRY_COMPARATOR);
+        StringBuilder result = new StringBuilder(title).append(":\n");
+        for (Entry entry : sorted) {
+            result.append(reportEntry(entry)).append("\n");
+        }
+        return result.toString();
+    }
+
+    private String report() {
+        return "";
+    }
+
+    private Path resolvePathFollowingLinks(String fileName) throws IOException {
+        Path path = storeFolderPath.resolve(fileName).toAbsolutePath().normalize();
+        Set<Path> visited = new HashSet<>();
+        for (int i = 0; i < 64; i++) {
+            Path current = path.getRoot();
+            if (current == null) {
+                current = Paths.get("").toAbsolutePath().getRoot();
+            }
+            for (Path component : path) {
+                current = current.resolve(component);
+                if (Files.isSymbolicLink(current)) {
+                    Path absoluteCurrent = current.toAbsolutePath().normalize();
+                    if (!visited.add(absoluteCurrent)) {
+                        throw new IOException("Symbolic link loop");
+                    }
+                    Path target = Files.readSymbolicLink(current);
+                    path = (target.isAbsolute() ? target : current.getParent().resolve(target)).toAbsolutePath().normalize();
+                    break;
+                }
+                if (component.equals(path.getFileName()) && !Files.isSymbolicLink(current)) {
+                    return path;
+                }
+            }
+            if (!containsSymbolicLink(path)) {
+                return path;
+            }
+        }
+        throw new IOException("Too many symbolic links");
+    }
+
+    private boolean containsSymbolicLink(Path path) {
+        Path current = path.getRoot();
+        for (Path component : path) {
+            current = current.resolve(component);
+            if (Files.isSymbolicLink(current)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private static final Comparator<Entry> ENTRY_COMPARATOR = Comparator.comparing(entry -> entry.description);
+
+    private static class Entry {
+        private final String description;
+        private final String fileName;
+        private FileResolution resolution;
+
+        private Entry(String description, String fileName) {
